module opponent_location(\n    input [9:0] l,\n    output reg [63:0] result_fixed\n);\n\n    // Precomputed 1/(πe) * 2^32 as Q32.32 format\n    localparam [63:0] INV_PI_E_FIXED = 64'h000000001DF1DA20;\n    \n    // Compute l² term\n    wire [19:0] l_squared = l * l;\n    wire [63:0] l_sq_fixed = {44'h0, l_squared, 32'h0};  // Shift to Q32.32 format\n    \n    // Multiply by 1/(πe)\n    wire [127:0] term1_full = l_sq_fixed * INV_PI_E_FIXED;\n    wire [63:0] term1 = term1_full[95:32];  // Extract Q32.32 portion\n    \n    // Compute denominator (l+1)\n    wire [9:0] denom = l + 10'd1;\n    \n    // Compute term2 = round(1/denom)\n    wire [63:0] numerator = {32'h00000000, 32'h00000001} << 32;  // 1 << 32\n    wire [63:0] round_term = {59'h0, denom} >> 1;  // denom/2\n    wire [63:0] scaled_numerator = numerator + round_term;\n    wire [63:0] term2_div = scaled_numerator / {54'h0, denom};\n    wire [63:0] term2 = {32'h00000000, term2_div[31:0]};\n    \n    always @(*) begin\n        result_fixed = term1 + term2;  // Fixed-point addition\n    end\n\nendmodule